import{_ as t,o as a,c as r,a5 as o}from"./chunks/framework.BfQ7H7Qx.js";const c="/brandhub-infrastructure/assets/system-architecture.C84lFwf5.png",g=JSON.parse('{"title":"System Architecture (docs/architecture/)","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/README.md","filePath":"architecture/README.md"}'),i={name:"architecture/README.md"};function d(n,e,s,l,h,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="system-architecture-docs-architecture" tabindex="-1">System Architecture (<code>docs/architecture/</code>) <a class="header-anchor" href="#system-architecture-docs-architecture" aria-label="Permalink to &quot;System Architecture (`docs/architecture/`)&quot;">​</a></h1><p>&gt; Navigation: <a href="./../">← Knowledge Base Hub</a> · <a href="./../adr/README.html">← ADR Index</a> · <a href="./../api/README.html">API Contracts →</a> · <a href="./../database/README.html">Database Design →</a> · <a href="./../operations/README.html">AWS Production Ops →</a></p><p>Authoritative architectural specifications, microservice ownership boundaries, inter-service REST/RabbitMQ/STOMP contracts, sequence flows, Hybrid GraphRAG blueprints, and interactive topology visualizers for <strong>BrandHub</strong>.</p><hr><h2 id="_1-end-to-end-system-topology" tabindex="-1">1. End-to-End System Topology <a class="header-anchor" href="#_1-end-to-end-system-topology" aria-label="Permalink to &quot;1. End-to-End System Topology&quot;">​</a></h2><p><img src="'+c+'" alt="BrandHub System Architecture"></p><ul><li><strong>Rendered High-Resolution Diagram</strong>: <code>docs/architecture/system/system-architecture.png</code> (embedded above)</li><li><strong>Editable Vector Source</strong>: <code>docs/architecture/system/system-architecture.drawio</code> (open with <code>diagrams.net</code> or the VS Code Draw.io extension; historical V1 source is archived in <a href="./../archive/v1-legacy/README.html">V1 Legacy Archive</a>)</li></ul><hr><h2 id="_2-core-architecture-specifications-md" tabindex="-1">2. Core Architecture Specifications (<code>.md</code>) <a class="header-anchor" href="#_2-core-architecture-specifications-md" aria-label="Permalink to &quot;2. Core Architecture Specifications (`.md`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Document</th><th style="text-align:left;">Scope &amp; Code-Verified Highlights</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="./technical-overview.html">System Technical Overview</a></td><td style="text-align:left;">Master architectural synthesis across the <strong>6 Canonical Roles</strong> (<code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code>), <strong>141 FRs (<code>3.2.1</code>–<code>3.10.14</code>)</strong>, 7-repo Polyrepo, 5-engine Polyglot Persistence (<code>97</code> PG tables + <code>52</code> Mongo collections + Redis + ChromaDB + Neo4j), RS256 + <code>AES-256-GCM</code> + S3 Envelope Security, and AWS <code>ap-southeast-1</code> + Vast.ai deployment</td></tr><tr><td style="text-align:left;"><a href="./service-boundaries.html">Service Boundaries</a></td><td style="text-align:left;">Strict database, domain, and runtime ownership rules across <code>brandhub-api-gateway</code> (<code>:8080</code>), <code>brandhub-business-service</code> (<code>:8081</code>), <code>brandhub-ai-service</code> (<code>:8082</code>), <code>brandhub-publisher-service</code> (<code>:8083</code>), <code>brandhub-crawl</code> (<code>:8084</code>), <code>brandhub-web</code>, and <code>brandhub-mobile-app</code></td></tr><tr><td style="text-align:left;"><a href="./local-run-architecture.html">Local Run Architecture</a></td><td style="text-align:left;">Modular Docker Compose v2 <code>include:</code> graph (<code>docker/compose/dev/compose.yaml</code>, <code>dev-ai/compose.yaml</code>, 6 <code>shared/*.yaml</code> fragments), local <code>postgres:17-alpine</code> + <code>mongo:7.0</code> bootstrap, host hot-reload workflows, and Expo <code>:8090</code> mobile networking</td></tr><tr><td style="text-align:left;"><a href="./sequence-diagrams.html">Sequence Diagrams (4 Core Flows)</a></td><td style="text-align:left;">Mermaid sequence diagrams for Content Authoring &amp; Atomic AI Credit Reservation, 3-Tier Approval Sequence (<code>Creator -&gt; Manager -&gt; Client</code>), Asynchronous RabbitMQ Social Publishing, and RS256 Token Rotation</td></tr><tr><td style="text-align:left;"><a href="./business-ai-rest-contract.html"><code>business-service</code> ↔ <code>ai-service</code> REST Contract</a></td><td style="text-align:left;">Internal <code>/api/v1/ai/*</code>, <code>/api/v2/ai/image/*</code>, and <code>/internal/ai/*</code> contracts, <code>X-Internal-Key</code> security, <code>ProductVideoProduction</code> durable coordinator &amp; Vast.ai Wan 2.2 VACE orchestration, and double-entry AI credit settlement</td></tr><tr><td style="text-align:left;"><a href="./ai-service-architecture.html">AI Service Internal Architecture</a></td><td style="text-align:left;">FastAPI router/service layering (<code>15</code> routers), ChromaDB <code>384d</code> tenant isolation, Neo4j Trend Knowledge Graph, Groq/Gemini/Claude LLM routing, Qwen Image 2.1 + Wan 2.2 Fun VACE/S2V GPU workers, and <code>Edit_Video</code> server auto-editing</td></tr><tr><td style="text-align:left;"><a href="./brand-rag-pipeline-design.html">Brand Knowledge Base RAG Pipeline Design</a></td><td style="text-align:left;">Dual Hybrid GraphRAG (ChromaDB <code>384d</code> HNSW + Neo4j APOC Entity Resolution), <code>500</code>-char / <code>50</code>-overlap chunking, S3 URI conventions, and hallucination checks</td></tr><tr><td style="text-align:left;"><a href="./ai-content-flow.html">Current AI Content Generation Flow</a></td><td style="text-align:left;">Code-verified comparison of quick <code>Generate with AI</code> vs. 3-variant Brand Hybrid GraphRAG caption generation (<code>HOOK_DRIVEN</code>, <code>STORYTELLING</code>, <code>DIRECT_CTA</code>) with Neo4j trend evidence, PhoBERT emotion signals, and Humanizer</td></tr></tbody></table><hr><h2 id="_3-interactive-architecture-visualizers-html" tabindex="-1">3. Interactive Architecture Visualizers (<code>.html</code>) <a class="header-anchor" href="#_3-interactive-architecture-visualizers-html" aria-label="Permalink to &quot;3. Interactive Architecture Visualizers (`.html`)&quot;">​</a></h2><p>All standalone visualizers open directly inside the VitePress HTML Viewer:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Interactive Diagram</th><th style="text-align:left;">What It Visualizes</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/brandhub-infrastructure/view.html?file=architecture/architecture.html">System Architecture &amp; Auth Role-Check Flow</a></td><td style="text-align:left;">Client Layer (<code>brandhub-web</code>, <code>brandhub-mobile-app</code>), <code>brandhub-api-gateway</code> WebFlux filter chain, backend microservices, polyglot stores, <strong>4 social APIs (Facebook, Instagram, TikTok, Threads)</strong>, and 2-tier RBAC evaluation</td></tr><tr><td style="text-align:left;"><a href="/brandhub-infrastructure/view.html?file=architecture/db-ownership-diagram.html">Database Ownership &amp; Cross-DB Reference Map</a></td><td style="text-align:left;">Per-service ownership across <code>97</code> PostgreSQL tables, <code>52</code> MongoDB collections, ChromaDB, Neo4j, Redis, and S3, plus soft-UUID join and transactional outbox patterns</td></tr><tr><td style="text-align:left;"><a href="/brandhub-infrastructure/view.html?file=architecture/polyrepo-structure.html">Polyrepo Structure &amp; Codebase Map</a></td><td style="text-align:left;">Interactive directory tree and tech-stack metadata across all 7 <code>BrandHubOrganization</code> repositories</td></tr><tr><td style="text-align:left;"><a href="/brandhub-infrastructure/view.html?file=architecture/rabbitmq-publisher-contract.html">RabbitMQ Publisher Contract</a></td><td style="text-align:left;">Queue/exchange topology (<code>publisher.job.exchange</code>, <code>publisher.retry.exchange</code> <code>1m</code>/<code>5m</code>/<code>15m</code> TTL delay queues, <code>publisher.job.dlq</code>) and <code>PublishJobMessage</code> JSON contracts</td></tr><tr><td style="text-align:left;"><a href="/brandhub-infrastructure/view.html?file=architecture/social-platforms-api-specs.html">Social Platforms API Specifications</a></td><td style="text-align:left;">Container lifecycles, OAuth scopes, rate limits, and retry classification for <strong>Facebook Graph v19.0</strong>, <strong>Instagram Graph v19.0</strong>, <strong>TikTok Content Posting v2</strong>, and <strong>Threads Publishing API</strong></td></tr></tbody></table>',14)])])}const b=t(i,[["render",d]]);export{g as __pageData,b as default};
